import { MCPTool } from '@modelcontextprotocol/core';
import { CalendarMCPServer } from '../server';
import { logger } from '../utils/logger';

export class ToolRegistry {
  private server: CalendarMCPServer;
  private tools: MCPTool[] = [];

  constructor(server: CalendarMCPServer) {
    this.server = server;
  }

  public registerTool(tool: MCPTool): void {
    this.tools.push(tool);
    this.server.registerTool(tool);
    logger.info(`Registered tool: ${tool.name}`);
  }

  public registerAllTools(): void {
    // Import and register all tools
    const getEventsTools = require('./get-events').default;
    const createEventTool = require('./create-event').default;
    // Add more tools as they are implemented

    this.registerTool(getEventsTools);
    this.registerTool(createEventTool);

    logger.info(`Registered ${this.tools.length} tools`);
  }
}
```
