```typescript
import { MCPTool, MCPRequest, MCPResponse } from '@modelcontextprotocol/core';
import { EventKitService } from '../eventkit';
import { logger } from '../utils/logger';

const eventKitService = new EventKitService();

const getEventsSchema = {
  type: 'object',
  properties: {
    startDate: { type: 'string', format: 'date-time' },
    endDate: { type: 'string', format: 'date-time' },
    calendarIds: { type: 'array', items: { type: 'string' }, optional: true },
    limit: { type: 'number', optional: true }
  },
  required: ['startDate', 'endDate']
};

const getEventsTool: MCPTool = {
  name: 'get_events',
  description: 'Fetch calendar events within a specified date range',
  schema: getEventsSchema,
  execute: async (request: MCPRequest): Promise<MCPResponse> => {
    try {
      const { startDate, endDate, calendarIds, limit } = request.params;

      // Parse dates from ISO strings
      const start = new Date(startDate);
      const end = new Date(endDate);

      // Validate date range
      if (start > end) {
        return {
          status: 'error',
          error: 'Start date must be before end date'
        };
      }

      // Get events from EventKit
      const events = await eventKitService.getEvents(start, end, calendarIds);

      // Apply limit if specified
      const limitedEvents = limit ? events.slice(0, limit) : events;

      return {
        status: 'success',
        result: limitedEvents
      };
    } catch (error) {
      logger.error('Error fetching events:', error);
      return {
        status: 'error',
        error: `Failed to fetch events: ${error.message}`
      };
    }
  }
};

export default getEventsTool;
```
