1. Create `src/tools/create-event.ts` to implement the event creation tool:
```typescript
import { MCPTool, MCPRequest, MCPResponse } from '@modelcontextprotocol/core';
import { EventKitService } from '../eventkit';
import { validateEvent } from '../utils/validation';
import { logger } from '../utils/logger';

const eventKitService = new EventKitService();

const createEventSchema = {
  type: 'object',
  properties: {
    title: { type: 'string' },
    description: { type: 'string', optional: true },
    startDate: { type: 'string', format: 'date-time' },
    endDate: { type: 'string', format: 'date-time' },
    isAllDay: { type: 'boolean', optional: true },
    location: { type: 'string', optional: true },
    calendarId: { type: 'string' },
    attendees: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          name: { type: 'string' },
          email: { type: 'string' }
        },
        required: ['email']
      },
      optional: true
    },
    recurrence: {
      type: 'object',
      properties: {
        frequency: { type: 'string', enum: ['daily', 'weekly', 'monthly', 'yearly'] },
        interval: { type: 'number' },
        endDate: { type: 'string', format: 'date-time', optional: true },
        occurrences: { type: 'number', optional: true }
      },
      required: ['frequency', 'interval'],
      optional: true
    }
  },
  required: ['title', 'startDate', 'endDate', 'calendarId']
};

const createEventTool: MCPTool = {
  name: 'create_event',
  description: 'Create a new calendar event',
  schema: createEventSchema,
  execute: async (request: MCPRequest): Promise<MCPResponse> => {
    try {
      const eventData = request.params;

      // Parse dates from ISO strings
      eventData.startDate = new Date(eventData.startDate);
      eventData.endDate = new Date(eventData.endDate);
      if (eventData.recurrence?.endDate) {
        eventData.recurrence.endDate = new Date(eventData.recurrence.endDate);
      }

      // Validate event data
      const validationResult = validateEvent(eventData);
      if (!validationResult.valid) {
        return {
          status: 'error',
          error: `Invalid event data: ${validationResult.errors.join(', ')}`
        };
      }

      // Create event in EventKit
      const createdEvent = await eventKitService.createEvent(eventData);

      return {
        status: 'success',
        result: createdEvent
      };
    } catch (error) {
      logger.error('Error creating event:', error);
      return {
        status: 'error',
        error: `Failed to create event: ${error.message}`
      };
    }
  }
};

export default createEventTool;
```
