import * as winston from 'winston';
import * as path from 'path';
import * as os from 'os';

// Define log directory - use user's home directory for logs
const logDir = path.join(os.homedir(), '.calendar-mcp-server', 'logs');

// Create logger instance
export const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.json()
  ),
  defaultMeta: { service: 'calendar-mcp-server' },
  transports: [
    // Console transport for development
    new winston.transports.Console({
      format: winston.format.combine(
        winston.format.colorize(),
        winston.format.simple()
      )
    }),
    // File transport for persistent logs
    new winston.transports.File({ 
      filename: path.join(logDir, 'error.log'), 
      level: 'error' 
    }),
    new winston.transports.File({ 
      filename: path.join(logDir, 'combined.log') 
    })
  ]
});

// Create error handling utility
export class ErrorHandler {
  static handleError(error: Error, context?: string): void {
    logger.error({
      message: error.message,
      stack: error.stack,
      context
    });
  }

  static createMCPError(message: string, code?: string): any {
    return {
      status: 'error',
      error: {
        message,
        code: code || 'INTERNAL_ERROR'
      }
    };
  }
}
