2. Create a CLI entry point in `src/cli.ts`:
```typescript
#!/usr/bin/env node
import { CalendarMCPServer } from './server';
import { ToolRegistry } from './tools/registry';
import { logger } from './utils/logger';
import { parseArgs } from './utils/args-parser';

async function main() {
  try {
    // Parse command line arguments
    const config = parseArgs(process.argv.slice(2));

    // Initialize server
    const server = new CalendarMCPServer(config.port);

    // Register tools
    const registry = new ToolRegistry(server);
    registry.registerAllTools();

    // Start server
    await server.start();

    logger.info(`Calendar MCP Server running on port ${config.port}`);
    logger.info('Press Ctrl+C to stop the server');

    // Handle graceful shutdown
    process.on('SIGINT', async () => {
      logger.info('Shutting down server...');
      await server.stop();
      process.exit(0);
    });
  } catch (error) {
    logger.error('Failed to start server:', error);
    process.exit(1);
  }
}

main();
```
