1. Create `src/tools/get-calendars.ts` to implement calendar listing tool:
```typescript
import { MCPTool, MCPRequest, MCPResponse } from '@modelcontextprotocol/core';
import { EventKitService } from '../eventkit';
import { logger } from '../utils/logger';

const eventKitService = new EventKitService();

const getCalendarsSchema = {
  type: 'object',
  properties: {
    includeReadOnly: { type: 'boolean', optional: true }
  }
};

const getCalendarsTool: MCPTool = {
  name: 'get_calendars',
  description: 'List available calendars',
  schema: getCalendarsSchema,
  execute: async (request: MCPRequest): Promise<MCPResponse> => {
    try {
      const { includeReadOnly = true } = request.params;

      // Get calendars from EventKit
      let calendars = await eventKitService.getCalendars();

      // Filter read-only calendars if requested
      if (!includeReadOnly) {
        calendars = calendars.filter(cal => cal.allowsModifications);
      }

      return {
        status: 'success',
        result: calendars
      };
    } catch (error) {
      logger.error('Error fetching calendars:', error);
      return {
        status: 'error',
        error: `Failed to fetch calendars: ${error.message}`
      };
    }
  }
};

export default getCalendarsTool;
```
